<template><view class="detail-page"><view class="class-nav"><NativeStatusSpacer/><view class="nav-line"><button class="back" aria-label="返回" @tap="back">‹</button><text>班级详情</text></view></view><view class="class-body"><text v-if="busy" class="state">正在加载班级…</text><view v-if="error" class="state error">{{error}}<button @tap="load">重试</button></view><template v-if="classInfo">
<view class="class-summary"><view class="class-symbol"><PrototypeIcon name="people" :size="52"/></view><view class="class-summary-copy"><view class="class-heading"><text class="title">{{classInfo.name}}</text><text :class="['class-status',{disabled:classInfo.status!=='ENABLED'}]">{{classInfo.status==='ENABLED'?'正常':'停用'}}</text></view><text class="meta">{{classInfo.schoolName}}<template v-if="classInfo.gradeName"> · {{classInfo.gradeName}}</template></text><text v-if="studentsAllowed" class="meta">{{students.length}} 名成长小主人<template v-if="headTeacherName"> · 班主任 {{headTeacherName}}</template></text><text v-else-if="headTeacherName" class="meta">班主任 {{headTeacherName}}</text></view></view>
<view class="tabs"><button :class="{active:tab==='students'}" @tap="tab='students'">成员列表</button><button :class="{active:tab==='info'}" @tap="tab='info'">班级信息</button><button :class="{active:tab==='teachers'}" @tap="tab='teachers'">教学设置</button></view>
<view v-if="tab==='students'" class="member-list"><view v-if="studentsAllowed" class="search-shell"><view class="search-icon"/><input v-model="keyword" class="member-search" placeholder="搜索姓名、班级学号" maxlength="50"/></view><view v-if="studentsAllowed&&students.length" class="status-filter"><button :class="{active:statusFilter==='ALL'}" @tap="statusFilter='ALL'">全部</button><button :class="{active:statusFilter==='ACTIVE'}" @tap="statusFilter='ACTIVE'">在读</button></view><view v-if="batchMode" class="batch-controls"><text>已选 {{selectedMembers.length}} 人</text><button @tap="selectVisible">{{visibleStudents.length&&visibleStudents.every(s=>selectedMembers.includes(s.studentId))?'取消当前结果':'全选当前结果'}}</button></view><text v-if="batchError" class="state error">{{batchError}}</text><text v-if="!studentsAllowed" class="state">当前账号无学员关系查看权限</text><text v-else-if="!students.length" class="state">暂无当前班级成员</text><text v-if="studentsAllowed&&students.length&&!visibleStudents.length" class="state">没有匹配的成员</text><view v-for="student in visibleStudents" :key="student.studentId" class="row" @tap="openMember(student.studentId)"><view v-if="batchMode" :class="['member-check',{checked:selectedMembers.includes(student.studentId)}]"><text v-if="selectedMembers.includes(student.studentId)">✓</text></view><view class="avatar"><image src="/static/pixel/default-child-avatar.png" mode="aspectFill"/></view><view class="member-copy"><text class="name">{{student.studentName}}</text><text v-if="student.gradeCode" class="member-grade">{{student.gradeCode}}</text><text v-if="student.studentNumber" class="member-number">学号 {{student.studentNumber}}</text></view><text v-if="memberStatusLabel(student.studentStatus)" :class="['member-status',{disabled:student.studentStatus==='DISABLED'}]">{{memberStatusLabel(student.studentStatus)}}</text></view></view>
<view v-else-if="tab==='info'" class="info-list"><view><text>班级名称</text><text>{{classInfo.name}}</text></view><view><text>班级编码</text><text>{{classInfo.code}}</text></view><view><text>所属学校</text><text>{{classInfo.schoolName||'—'}}</text></view><view><text>所属年级</text><text>{{classInfo.gradeName||'—'}}</text></view><button v-if="canEdit" class="edit-button" :disabled="statusSaving" @tap="edit">编辑班级信息</button><text v-if="statusError" class="status-error">{{statusError}}</text><button v-if="statusAllowed()" class="class-status-action" :class="{danger:classInfo.status==='ENABLED'}" :disabled="statusSaving" @tap="changeStatus">{{statusSaving?'正在处理':classInfo.status==='ENABLED'?'停用班级':'启用班级'}}</button></view>
<view v-else class="teaching-list"><ClassAcademicSettings v-if="classInfo" :token="verifiedToken" :scope="verifiedOrganization" :class-id="classInfo.id" :editable="canEdit" @saved="name=>headTeacherName=name"/><text v-if="!teachersAllowed" class="state">当前账号无教师候选查看权限</text><text v-else-if="!teachers.length" class="state">暂无当前班级教师</text><view v-for="teacher in teachers" :key="teacher.userId" class="row"><view class="avatar"><PrototypeIcon name="user" :size="34"/></view><text class="name">{{teacher.displayName}}</text></view></view>
<view v-if="tab==='students'&&(batchAllowed()||addMemberAllowed())" class="class-footer"><template v-if="batchMode"><button class="batch-start" @tap="cancelBatch">取消选择</button><button class="add-member" :disabled="!selectedMembers.length" @tap="configureSelected">配置 {{selectedMembers.length}} 人</button></template><template v-else><button v-if="batchAllowed()" class="batch-start" @tap="startBatch">批量操作</button><button v-if="addMemberAllowed()" class="add-member" @tap="addMember">＋ 新增成员</button></template></view></template></view><view v-if="activeMember" class="member-overlay" @tap="activeMember=null"><view class="member-sheet" @tap.stop><view class="member-sheet-heading"><text>{{activeMember.studentName}}</text><button aria-label="关闭" @tap="activeMember=null">×</button></view><text v-if="memberStatusLabel(activeMember.studentStatus)" class="member-status">{{memberStatusLabel(activeMember.studentStatus)}}</text><StudentNumberEditor v-if="studentsAllowed" :key="activeMember.studentId" :token="verifiedToken" :scope="activeMember.enrollmentOrganizationId" :student-id="activeMember.studentId" :editable="studentsAllowed" @saved="value=>activeMember&&(activeMember.studentNumber=value)"/><button v-if="transferAllowed(activeMember)" class="transfer-entry member-action" @tap="requestTransfer(activeMember)">转学申请</button></view></view></view></template>
<script setup lang="ts">
import {academicMetadataApi} from '@/api/academic-metadata';
import ClassAcademicSettings from '@/components/ClassAcademicSettings.vue';
import NativeStatusSpacer from '@/components/NativeStatusSpacer.vue';

import {getMiniappCapabilities} from '@/api/capability';
import {ref,computed} from 'vue';import StudentNumberEditor from '@/components/StudentNumberEditor.vue';import {onLoad,onShow,onHide,onUnload} from '@dcloudio/uni-app';import PrototypeIcon from '@/components/PrototypeIcon.vue';import {request} from '@/api/http';import {getOrganizationSession} from '@/session/organization-session';import {listManagedClasses,listOrganizationTeachers,changeManagedClassStatus,type OrganizationClass,type OrganizationTeacherOption} from '@/api/organization-classes';import {listOrganizationStudents,type OrganizationStudentRelationship} from '@/api/organization-students';import {membersOfClass,classDetailRoute,memberStatusLabel,matchesClassMember} from '@/models/class-detail';import {toggleBatchMember,validateBatchSelection} from '@/models/class-batch-draft';
const headTeacherName=ref<string|null>(null);
const canChangeStatus=ref(false),statusSaving=ref(false),statusError=ref('');
const verifiedOrganization=ref('');
const activeMember=ref<OrganizationStudentRelationship|null>(null);const batchMode=ref(false),selectedMembers=ref<string[]>([]),batchError=ref('');const keyword=ref('');const statusFilter=ref<'ALL'|'ACTIVE'>('ALL');const visibleStudents=computed(()=>students.value.filter(s=>matchesClassMember(s,keyword.value)&&(statusFilter.value==='ALL'||s.studentStatus==='ENABLED')));
const classInfo=ref<OrganizationClass|null>(null),students=ref<OrganizationStudentRelationship[]>([]),teachers=ref<OrganizationTeacherOption[]>([]),busy=ref(false),error=ref(''),studentsAllowed=ref(false),teachersAllowed=ref(false),canEdit=ref(false),canAddMember=ref(false),canTransfer=ref(false),tab=ref('students');let id='',epoch=0,verifiedToken='',verifiedScope='';onLoad(q=>{id=typeof q?.classId==='string'?q.classId:'';});function clear(){canChangeStatus.value=false;statusSaving.value=false;statusError.value='';headTeacherName.value=null;verifiedOrganization.value='';activeMember.value=null;batchMode.value=false;selectedMembers.value=[];batchError.value='';keyword.value='';statusFilter.value='ALL';epoch++;classInfo.value=null;students.value=[];teachers.value=[];verifiedToken='';verifiedScope='';studentsAllowed.value=false;teachersAllowed.value=false;canEdit.value=false;canTransfer.value=false;canAddMember.value=false;}onHide(clear);onUnload(clear);
function scopeKey(){const s=uni.getStorageSync('lingdong.selected-organization') as {accessToken?:string;organizationId?:string}|undefined;return `${s?.accessToken||''}:${s?.organizationId||''}`;}
function active(n:number,t:string|undefined,scope:string){return n===epoch&&getOrganizationSession()?.accessToken===t&&scopeKey()===scope;}
async function load(){clear();const n=epoch,t=getOrganizationSession()?.accessToken,scope=scopeKey();busy.value=true;error.value='';try{classDetailRoute(id);if(!t)throw Error('请先登录');const me=await request<{permissionCodes:string[]}>('/auth/me',{header:{Authorization:`Bearer ${t}`}});if(!active(n,t,scope))return;if(!me.permissionCodes.includes('CLASS_READ'))throw Error('没有班级查看权限');const capabilities=await getMiniappCapabilities();if(!active(n,t,scope))return;if(!capabilities.organizationMiniappAuthEnabled||!capabilities.classManagementEnabled)throw Error('班级管理暂未开放');const classes=await listManagedClasses(t);if(!active(n,t,scope))return;const selected=classes.find(c=>c.id===id);if(!selected)throw Error('班级不在可管理范围');studentsAllowed.value=me.permissionCodes.includes('STUDENT_ORGANIZATION_MANAGE');teachersAllowed.value=['TEACHER_CLASS_ASSIGN','LEARNING_TASK_CREATE'].some(p=>me.permissionCodes.includes(p));canEdit.value=me.permissionCodes.includes('CLASS_UPDATE');canChangeStatus.value=me.permissionCodes.includes('CLASS_STATUS_CHANGE');canTransfer.value=studentsAllowed.value&&me.permissionCodes.includes('STUDENT_TRANSFER_REQUEST_CREATE');canAddMember.value=me.permissionCodes.includes('STUDENT_CLASS_ASSIGN')&&(me.permissionCodes.includes('STUDENT_CREATE')||studentsAllowed.value);const selectedOrganization=(uni.getStorageSync('lingdong.selected-organization') as {organizationId?:string})?.organizationId||'';const [members,staff,academic]=await Promise.all([studentsAllowed.value?listOrganizationStudents(t):Promise.resolve([]),teachersAllowed.value?listOrganizationTeachers(t,id):Promise.resolve([]),academicMetadataApi.readClass(t,selectedOrganization,id)]);if(!active(n,t,scope))return;if(academic.classId!==id)throw Error('班级配置响应范围不一致');headTeacherName.value=academic.headTeacherName||null;students.value=membersOfClass(members,id);teachers.value=staff.filter(r=>r.classOrganizationIds.includes(id));verifiedOrganization.value=(uni.getStorageSync('lingdong.selected-organization') as {organizationId?:string})?.organizationId||'';classInfo.value=selected;verifiedToken=t;verifiedScope=scope;}catch(e){if(active(n,t,scope))error.value=e instanceof Error?e.message:'班级加载失败';}finally{if(active(n,t,scope))busy.value=false;}}
function statusAllowed(){return canChangeStatus.value&&!!classInfo.value&&['ENABLED','DISABLED'].includes(classInfo.value.status)&&!!verifiedToken&&active(epoch,verifiedToken,verifiedScope);}
async function changeStatus(){
 if(statusSaving.value||!statusAllowed())return;
 const item=classInfo.value!,n=epoch,t=verifiedToken,scope=verifiedScope;
 const disabling=item.status==='ENABLED';
 statusSaving.value=true;statusError.value='';
 try{
  const confirmed=await new Promise<boolean>(resolve=>uni.showModal({title:disabling?'确认停用班级？':'确认启用班级？',content:disabling?'班内未完成的机构和教师任务将失效，历史记录继续保留。':'已失效的历史任务不会恢复。',confirmText:disabling?'确认停用':'确认启用',confirmColor:disabling?'#b42318':'#167c5a',success:result=>resolve(result.confirm),fail:()=>resolve(false)}));
  if(!confirmed||!active(n,t,scope)||!statusAllowed()||classInfo.value?.id!==item.id)return;
  await changeManagedClassStatus(t,item);
  if(!active(n,t,scope))return;
  await load();
 }catch(e){if(active(n,t,scope))statusError.value=e instanceof Error?e.message:'状态更新失败，请重试';}
 finally{if(n===epoch)statusSaving.value=false;}
}

function transferAllowed(student:OrganizationStudentRelationship):boolean{
 const selected=uni.getStorageSync('lingdong.selected-organization') as {organizationId?:string;typeCode?:string;accessToken?:string}|undefined;
 if(!canTransfer.value||getOrganizationSession()?.accessToken!==verifiedToken||scopeKey()!==verifiedScope||!students.value.some(s=>s.studentId===student.studentId&&s.enrollmentOrganizationId===student.enrollmentOrganizationId)||selected?.organizationId!==student.enrollmentOrganizationId||!['SCHOOL','TRAINING_INSTITUTION'].includes(selected.typeCode||''))return false;
 return /^[1-9]\d*$/.test(student.studentId)&&/^[1-9]\d*$/.test(student.enrollmentOrganizationId);
}
function requestTransfer(student:OrganizationStudentRelationship){
 if(!transferAllowed(student))return;
 uni.navigateTo({url:'/pages/transfer-proposal/transfer-proposal?mode=INSTITUTION&studentId='+encodeURIComponent(student.studentId)+'&sourceId='+encodeURIComponent(student.enrollmentOrganizationId)});
}
function edit(){if(canEdit.value&&getOrganizationSession()?.accessToken===verifiedToken&&scopeKey()===verifiedScope)uni.navigateTo({url:'/pages/organization-classes/organization-classes?editClassId='+encodeURIComponent(id)});}onShow(load);

function addMemberAllowed(){const selected=uni.getStorageSync('lingdong.selected-organization') as {organizationId?:string;typeCode?:string}|undefined;return !!selected&&canAddMember.value&&!!classInfo.value&&classInfo.value.status==='ENABLED'&&classInfo.value.effectiveStatus==='ENABLED'&&getOrganizationSession()?.accessToken===verifiedToken&&scopeKey()===verifiedScope&&selected?.organizationId===classInfo.value.schoolOrganizationId&&['SCHOOL','TRAINING_INSTITUTION'].includes(selected.typeCode||'');}
function addMember(){if(addMemberAllowed())uni.navigateTo({url:'/pages/organization-class-members/organization-class-members?classId='+encodeURIComponent(id)});}
function batchAllowed(){const s=uni.getStorageSync('lingdong.selected-organization') as {organizationId?:string;typeCode?:string}|undefined;return !!s&&studentsAllowed.value&&!!classInfo.value&&classInfo.value.status==='ENABLED'&&classInfo.value.effectiveStatus==='ENABLED'&&getOrganizationSession()?.accessToken===verifiedToken&&scopeKey()===verifiedScope&&s.organizationId===classInfo.value.schoolOrganizationId&&['SCHOOL','TRAINING_INSTITUTION'].includes(s.typeCode||'');}
function startBatch(){if(!batchAllowed())return;batchError.value='';if(!students.value.length){batchError.value='当前班级暂无可选成员';return;}batchMode.value=true;selectedMembers.value=[];}
function cancelBatch(){batchMode.value=false;selectedMembers.value=[];batchError.value='';}
function openMember(studentId:string){
 if(busy.value||!studentsAllowed.value||!verifiedToken||getOrganizationSession()?.accessToken!==verifiedToken||verifiedScope!==scopeKey())return;
 if(batchMode.value){toggleMember(studentId);return;}
 activeMember.value=students.value.find(row=>row.studentId===studentId)||null;
}
function toggleMember(studentId:string){if(!batchMode.value||!batchAllowed())return;try{selectedMembers.value=toggleBatchMember(selectedMembers.value,studentId,students.value.map(s=>s.studentId));batchError.value='';}catch(e){batchError.value=e instanceof Error?e.message:'选择未完成';}}
function selectVisible(){if(!batchMode.value||!batchAllowed())return;const visibleIds=visibleStudents.value.map(s=>s.studentId);if(!visibleIds.length)return;try{let next=[...selectedMembers.value];if(visibleIds.every(id=>next.includes(id)))next=next.filter(id=>!visibleIds.includes(id));else for(const id of visibleIds)if(!next.includes(id))next=toggleBatchMember(next,id,students.value.map(s=>s.studentId));selectedMembers.value=next;batchError.value='';}catch(e){batchError.value=e instanceof Error?e.message:'选择未完成';}}
function configureSelected(){if(!batchAllowed())return;try{const ids=validateBatchSelection(selectedMembers.value);if(ids.some(id=>!students.value.some(s=>s.studentId===id)))throw Error('成员关系已变化，请刷新');uni.navigateTo({url:'/pages/organization-class-batch/organization-class-batch?classId='+encodeURIComponent(id)+'&ids='+encodeURIComponent(ids.join(','))});}catch(e){batchError.value=e instanceof Error?e.message:'请选择成员';}}
function back(){uni.navigateBack({fail:()=>uni.reLaunch({url:'/pages/organization-classes/organization-classes'})});}
</script>
<style scoped>.detail-page{min-height:100vh;background:linear-gradient(#fff,#f5f9f6);color:#183a30;box-sizing:border-box}.class-nav{background:#fff}.nav-line{height:88rpx;display:flex;align-items:center;justify-content:center;position:relative;font-size:30rpx;font-weight:650}.back{position:absolute;left:15rpx;top:0;width:55rpx;height:88rpx;line-height:77rpx;font-size:58rpx;font-weight:300;background:transparent;margin:0;padding:0;color:#173e31}.back::after,button::after{border:0}.class-body{padding:15rpx 26rpx 40rpx}.class-summary{display:flex;gap:22rpx;align-items:center;border-radius:22rpx;background:#eff5f1;padding:22rpx}.class-symbol{width:124rpx;height:124rpx;display:flex;align-items:center;justify-content:center;background:#e5f1fa;border-radius:24rpx;flex-shrink:0}.class-summary-copy{min-width:0;flex:1}.class-heading{display:flex;gap:16rpx;align-items:center;min-width:0}.title{font-size:32rpx;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}.class-status{flex-shrink:0;border-radius:20rpx;padding:3rpx 14rpx;font-size:22rpx;color:#188257;background:#dff5e8}.class-status.disabled{color:#8d7866;background:#f0e9e3}.meta{display:block;font-size:24rpx;color:#89938f;margin-top:7rpx;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.tabs{display:flex;gap:6rpx;margin:12rpx 0}.tabs button{flex:1;margin:0;padding:0;line-height:70rpx;font-size:28rpx;background:#f3f6f4;border-radius:16rpx;color:#86918c;border-bottom:4rpx solid transparent}.tabs button.active{color:#146044;border-bottom-color:#146044;font-weight:650;background:#fff}.search-shell{display:flex;align-items:center;gap:12rpx;border:1rpx solid #e0e7e2;border-radius:20rpx;padding:10rpx 20rpx;background:#f9fbfa;margin:0 0 12rpx}.member-search{flex:1;min-width:0;height:58rpx;font-size:26rpx}.status-filter{display:flex;gap:12rpx;margin:0 0 12rpx}.status-filter button{flex-shrink:0;margin:0;padding:0 22rpx;line-height:54rpx;height:54rpx;font-size:24rpx;border-radius:999rpx;background:#eef3ef;color:#5f7168}.status-filter button.active{background:#155c43;color:#fff;font-weight:600}.row{display:flex;gap:14rpx;align-items:center;padding:12rpx 0;border-bottom:1rpx solid #e7eee8}.row:last-child{border-bottom:0}.avatar{width:54rpx;height:54rpx;display:flex;align-items:center;justify-content:center;flex-shrink:0;background:#edf5ee;border-radius:50%}.avatar image{width:100%;height:100%;border-radius:50%}.member-copy{min-width:0;flex:1}.name{font-size:28rpx;font-weight:650;display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.transfer-entry{margin:0 0 0 auto;flex-shrink:0;padding:0 16rpx;line-height:52rpx;background:#edf5f0;color:#205e49;font-size:23rpx;border-radius:14rpx}.state{display:block;color:#829089;font-size:25rpx;padding:26rpx 0}.error{color:#ac5147}.info-list>view{display:flex;justify-content:space-between;gap:26rpx;padding:25rpx 0;border-bottom:1rpx solid #e6eee8;font-size:27rpx}.info-list>view>text:first-child{color:#839188;flex-shrink:0}.info-list>view>text:last-child{text-align:right;overflow-wrap:anywhere}.edit-button{margin-top:30rpx;background:#155c43;color:#fff;border-radius:20rpx;font-size:28rpx}</style>
<style scoped>.search-icon{width:22rpx;height:22rpx;box-sizing:border-box;border:2rpx solid #83908b;border-radius:50%;position:relative;margin:0 7rpx 5rpx 0;flex-shrink:0}.search-icon::after{content:"";position:absolute;width:10rpx;height:2rpx;background:#83908b;transform:rotate(45deg);right:-7rpx;bottom:-4rpx}</style>

<style scoped>.class-footer{padding-top:25rpx}.add-member{background:#155e45;color:#fff;border-radius:18rpx;font-size:28rpx;line-height:86rpx}</style>

<style scoped>.class-body{padding-bottom:calc(140rpx + env(safe-area-inset-bottom))}.class-footer{position:fixed;left:0;right:0;bottom:0;display:flex;gap:18rpx;z-index:5;background:#fff;padding:16rpx 26rpx calc(16rpx + env(safe-area-inset-bottom));border-top:1rpx solid #e1ebe3;box-sizing:border-box}.class-footer button{flex:1;margin:0;line-height:82rpx;font-size:27rpx}.batch-start{border:1rpx solid #2d7659;border-radius:18rpx;background:#fff;color:#206549}.add-member[disabled]{background:#a7beb0;color:#fff}.batch-controls{display:flex;align-items:center;justify-content:space-between;font-size:25rpx;color:#47745b;margin-bottom:10rpx}.batch-controls button{font-size:24rpx;line-height:54rpx;padding:0 16rpx;margin:0;background:#edf5ef;color:#2a6a4c}.member-check{width:32rpx;height:32rpx;border-radius:50%;border:2rpx solid #b4c8bb;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:23rpx;color:#fff}.member-check.checked{background:#17674a;border-color:#17674a}</style>

<style scoped>.member-status{flex-shrink:0;font-size:22rpx;color:#267ed0;background:#e9f4ff;border-radius:20rpx;padding:3rpx 14rpx}.member-status.disabled{color:#987365;background:#f4eae3}</style>

<style scoped>.member-overlay{position:fixed;inset:0;background:rgba(16,39,29,.28);z-index:20;display:flex;align-items:flex-end}.member-sheet{width:100%;box-sizing:border-box;background:#fff;border-radius:28rpx 28rpx 0 0;padding:28rpx 30rpx calc(32rpx + env(safe-area-inset-bottom))}.member-sheet-heading{display:flex;align-items:center;gap:20rpx;margin-bottom:24rpx;font-size:30rpx;font-weight:650}.member-sheet-heading>text{flex:1;min-width:0;overflow-wrap:anywhere}.member-sheet-heading button{margin:0;background:transparent;padding:0 12rpx;font-size:42rpx;color:#6b8174}.member-action{display:block;width:100%;margin-top:28rpx;line-height:82rpx;font-size:28rpx}</style>

<style scoped>.member-copy{display:flex;align-items:center;gap:16rpx}.member-copy .name{flex:1;min-width:0}.member-number{font-size:23rpx;color:#7c8982;max-width:180rpx;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex-shrink:0}.member-grade{font-size:23rpx;color:#7c8982;max-width:160rpx;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex-shrink:0}</style>

<style scoped>.class-status-action{margin-top:18rpx;background:#e5f1e9;color:#17664e;font-size:27rpx;border-radius:16rpx;padding:18rpx}.class-status-action.danger{background:#fff0e9;color:#ad4f3f}.status-error{display:block;color:#ad4f3f;font-size:24rpx;margin-top:16rpx}</style>

<style scoped>.info-list>view{display:flex;align-items:flex-start;gap:24rpx}.info-list>view>text:first-child{flex:0 0 144rpx;white-space:nowrap}.info-list>view>text:last-child{flex:1;min-width:0;text-align:right;overflow-wrap:anywhere;white-space:normal}</style>

<style scoped>
